create PROCEDURE O7CRASWO_CREATEASSETREPAIRBINRECORD
                                    @sEvent   nvarchar(30), 
                                    @sPart    nvarchar(30),
                                    @sPartorg nvarchar(15),
                                    @sAsset    nvarchar(30),
									@sAssetorg nvarchar(15),
                                    @sStore   nvarchar(15),
                                    @sBin     nvarchar(15),
                                    @sLot     nvarchar(12),
                                    @nQty     numeric(24,6)

AS
	SET NOCOUNT ON


    DELETE FROM r5repairbins
    WHERE  rpb_part        = @sPart
    AND    rpb_part_org    = @sPartorg
    AND    rpb_store       = @sStore
    AND    rpb_object      = @sAsset
    AND    rpb_object_org  = @sAssetorg

    IF coalesce( @nQty, 0 ) > 0 
    INSERT INTO r5repairbins ( rpb_part, rpb_part_org, rpb_store, rpb_bin,  rpb_lot,      rpb_event, rpb_qty,  rpb_object,   rpb_object_org  )
    VALUES ( @sPart, @sPartorg, @sStore, @sBin,  coalesce(@sLot, N'*'),     @sEvent, 0,  @sAsset,   @sAssetorg )


-- ========================================

create PROCEDURE O7CRASWO_CREATEREPAIRBINRECORD
                                    @sEvent   nvarchar(30), 
                                    @sPart    nvarchar(30),
                                    @sPartorg nvarchar(15),
                                    @sStore   nvarchar(15),
                                    @sBin     nvarchar(15),
                                    @sLot     nvarchar(12),
                                    @nQty     numeric(24,6)

AS
	SET NOCOUNT ON


    DELETE FROM r5repairbins
    WHERE  rpb_part     = @sPart
    AND    rpb_part_org = @sPartorg
    AND    rpb_store    = @sStore
    AND    rpb_bin      = @sBin
    AND    rpb_lot      = @sLot
    AND    rpb_req      IS NULL
    AND    coalesce( rpb_event, @sEvent) = @sEvent

    IF coalesce( @nQty, 0 ) > 0 
        INSERT INTO r5repairbins ( rpb_part, rpb_part_org, rpb_store,rpb_bin,  rpb_lot, rpb_event,rpb_qty )
        VALUES ( @sPart, @sPartorg, @sStore, @sBin,  @sLot,     @sEvent, @nQty )


