create procedure O7CRBOO1	@sEvent			nvarchar(30),
							@nAct			numeric(8),
							@dDate			datetime,
							@sTrade			nvarchar(15),
							@sMrc			nvarchar(15),
							@sPerson		nvarchar(15),
							@sOctype		nvarchar(4),
							@sOcrtype		nvarchar(4),
							@nTothours		numeric(30,6),
							@nRate			numeric(24,6),
							@nCost			numeric(24,6),
							@dEntered		datetime,
							@sCorrection	nvarchar(1),
							@sOrder			nvarchar(30),
							@sOrderorg		nvarchar(15),
							@nOrdline		numeric(8),
							@sRtype			nvarchar(4),
							@nObjects		int,
							@sSplithours	nvarchar(1),
                            @sDesc            nvarchar(80),
                            @sParent          nvarchar(30),
                            @sMisc            nvarchar(1),
                            @nTaxamount       numeric(24,6),
                            @dCorrdate        datetime,
                            @sUdfchar01       nvarchar(80),
                            @sUdfchar02       nvarchar(80),
                            @sUdfchar03       nvarchar(80),
                            @sUdfchar04       nvarchar(80),
                            @sUdfchar05       nvarchar(80),
                            @sUdfchar06       nvarchar(80),
                            @sUdfchar07       nvarchar(80),
                            @sUdfchar08       nvarchar(80),
                            @sUdfchar09       nvarchar(80),
                            @sUdfchar10       nvarchar(80),
                            @sUdfchar11       nvarchar(80),
                            @sUdfchar12       nvarchar(80),
                            @sUdfchar13       nvarchar(80),
                            @sUdfchar14       nvarchar(80),
                            @sUdfchar15       nvarchar(80),
                            @sUdfchar16       nvarchar(80),
                            @sUdfchar17       nvarchar(80),
                            @sUdfchar18       nvarchar(80),
                            @sUdfchar19       nvarchar(80),
                            @sUdfchar20       nvarchar(80),
                            @sUdfchar21       nvarchar(80),
                            @sUdfchar22       nvarchar(80),
                            @sUdfchar23       nvarchar(80),
                            @sUdfchar24       nvarchar(80),
                            @sUdfchar25       nvarchar(80),
                            @sUdfchar26       nvarchar(80),
                            @sUdfchar27       nvarchar(80),
                            @sUdfchar28       nvarchar(80),
                            @sUdfchar29       nvarchar(80),
                            @sUdfchar30       nvarchar(80),
                            @nUdfnum01        numeric(24,6),
                            @nUdfnum02        numeric(24,6),
                            @nUdfnum03        numeric(24,6),
                            @nUdfnum04        numeric(24,6),
                            @nUdfnum05        numeric(24,6),
                            @dUdfdate01       datetime,
                            @dUdfdate02       datetime,
                            @dUdfdate03       datetime,
                            @dUdfdate04       datetime,
                            @dUdfdate05       datetime,
                            @sUdfchkbox01     nvarchar(1),
                            @sUdfchkbox02     nvarchar(1),
                            @sUdfchkbox03     nvarchar(1),
                            @sUdfchkbox04     nvarchar(1),
                            @sUdfchkbox05     nvarchar(1),
                            @sCurrentCrew     nvarchar(15),
                            @sCurrentCrewOrg  nvarchar(15),
                            @sCrew            nvarchar(15),
                            @sCrewOrg         nvarchar(15),
                            @sCorrectionref   nvarchar(30)
as
	SET NOCOUNT ON
	declare @nHours		numeric(24,6)
	declare @nTax		numeric(24,6)
	declare @nRecs		integer
	declare @sActEvent	nvarchar(30)
	declare @nActAct	numeric(8)

   declare c_evt cursor local static for  SELECT a1.act_event, a1.act_act
									FROM   r5activities a1,
										   r5activities a2,
										   r5events
									WHERE  evt_code        = a1.act_event
									AND    evt_routeparent = @sEvent
									AND    ( @sSplithours = N'A' OR ( @sSplithours = N'O' AND evt_rstatus <> N'C' ) )
									AND    a2.act_event    = @sEvent
									AND    a2.act_act      = @nAct
									AND    a2.act_act      = a1.act_act
									ORDER BY evt_code
	set @nRecs = 0
	set @nHours = round( @nTothours / @nObjects, 6)
	set @nTax = round( @nTaxamount / @nObjects, 6)
	open c_evt
	fetch next from c_evt into @sActEvent, @nActAct
	while @@FETCH_STATUS = 0
		begin
			set @nRecs = @nRecs + 1
			if @nRecs = @nObjects
				begin
					set @nHours = @nTothours - ( @nHours * (@nRecs - 1) )
					set @nTax = @nTaxamount - ( @nTax * (@nRecs - 1) )
				end
			INSERT INTO r5bookedhours
				 (   boo_event,
					 boo_act,
					 boo_date,
					 boo_trade,
					 boo_mrc,
					 boo_person,
					 boo_octype,
					 boo_ocrtype,
					 boo_hours,
					 boo_rate,
					 boo_cost,
					 boo_entered,
					 boo_correction,
					 boo_order,
					 boo_order_org,
					 boo_ordline,
					 boo_routerec,
					 boo_routertype,
					 boo_splithours,
					 boo_desc,
					 boo_routeparent,
					 boo_misc,
					 boo_taxamount,
					 boo_correctiondate,
					 boo_udfchar01,
					 boo_udfchar02,
					 boo_udfchar03,
					 boo_udfchar04,
					 boo_udfchar05,
					 boo_udfchar06,
					 boo_udfchar07,
					 boo_udfchar08,
					 boo_udfchar09,
					 boo_udfchar10,
					 boo_udfchar11,
					 boo_udfchar12,
					 boo_udfchar13,
					 boo_udfchar14,
					 boo_udfchar15,
					 boo_udfchar16,
					 boo_udfchar17,
					 boo_udfchar18,
					 boo_udfchar19,
					 boo_udfchar20,
					 boo_udfchar21,
					 boo_udfchar22,
					 boo_udfchar23,
					 boo_udfchar24,
					 boo_udfchar25,
					 boo_udfchar26,
					 boo_udfchar27,
					 boo_udfchar28,
					 boo_udfchar29,
					 boo_udfchar30,
					 boo_udfnum01,
					 boo_udfnum02,
					 boo_udfnum03,
					 boo_udfnum04,
					 boo_udfnum05,
					 boo_udfdate01,
					 boo_udfdate02,
					 boo_udfdate03,
					 boo_udfdate04,
					 boo_udfdate05,
					 boo_udfchkbox01,
					 boo_udfchkbox02,
					 boo_udfchkbox03,
					 boo_udfchkbox04,
					 boo_udfchkbox05,
					 boo_currentcrew,
					 boo_currentcrew_org,
					 boo_crew,
					 boo_crew_org,
					 boo_correction_ref)
			VALUES ( @sActEvent,
					 @nActAct,
					 @dDate,
					 @sTrade,
					 @sMrc,
					 @sPerson,
					 @sOctype,
					 @sOcrtype,
					 @nHours,
					 @nRate,
					 ( @nHours * @nRate ) + ISNULL( @nTax, 0 ),
					 @dEntered,
					 @sCorrection,
					 @sOrder,
					 @sOrderorg,
					 @nOrdline,
					 N'+',
					 @sRtype,
					 N'N',
					 @sDesc,
					 @sParent,
					 @sMisc,
					 @nTax,
					 @dCorrdate,
					 @sUdfchar01,
					 @sUdfchar02,
					 @sUdfchar03,
					 @sUdfchar04,
					 @sUdfchar05,
					 @sUdfchar06,
					 @sUdfchar07,
					 @sUdfchar08,
					 @sUdfchar09,
					 @sUdfchar10,
					 @sUdfchar11,
					 @sUdfchar12,
					 @sUdfchar13,
					 @sUdfchar14,
					 @sUdfchar15,
					 @sUdfchar16,
					 @sUdfchar17,
					 @sUdfchar18,
					 @sUdfchar19,
					 @sUdfchar20,
					 @sUdfchar21,
					 @sUdfchar22,
					 @sUdfchar23,
					 @sUdfchar24,
					 @sUdfchar25,
					 @sUdfchar26,
					 @sUdfchar27,
					 @sUdfchar28,
					 @sUdfchar29,
					 @sUdfchar30,
					 @nUdfnum01,
					 @nUdfnum02,
					 @nUdfnum03,
					 @nUdfnum04,
					 @nUdfnum05,
					 @dUdfdate01,
					 @dUdfdate02,
					 @dUdfdate03,
					 @dUdfdate04,
					 @dUdfdate05,
					 @sUdfchkbox01,
					 @sUdfchkbox02,
					 @sUdfchkbox03,
					 @sUdfchkbox04,
					 @sUdfchkbox05,
					 @sCurrentCrew,
