CREATE PROCEDURE O7CREPSL 
   @sCcode        nvarchar(30),
   @sChk          nvarchar(5) OUTPUT,
   @nOrderlines   int OUTPUT
AS
	SET NOCOUNT ON

	    declare @nVIncrNum                 numeric(38,0), -- NUMBER
		    @sVIncrNum		       nvarchar(30),
		    @sCheckResult              nvarchar(3),
		    @nAttach                   int, 		-- NUMBER = 0
		    @nSmrecvqty                numeric(24,6),
		    @nOrlqty                   numeric(24,6),
		    @nDklqty                   numeric(24,6),
		    @nPslqty                   numeric(24,6),
		    @nDck_qty                  numeric(24,6),
		    @nPendqty                  numeric(24,6),
		    @nLine                     numeric(8,0),  -- = 0
		    @nMaxpslline               numeric(8,0),  -- = 0
		    @sVDockStatus              nvarchar(4),  --R5DOCKRECEIPTS.DCK_STATUS%TYPE
		    @sVDockLineStatus          nvarchar(4), --R5DOCKLINES.DKL_LINESTATUS%TYPE
		    @sVDockOrg                 nvarchar(15), --R5DOCKRECEIPTS.DCK_ORG%TYPE
		    @sVSupplier                nvarchar(30), --R5DOCKRECEIPTS.DCK_SUPPLIER%TYPE
		    @sVSupplierOrg             nvarchar(15), --R5DOCKRECEIPTS.DCK_SUPPLIER_ORG%TYPE
		    @sVStore                   nvarchar(15), --R5DOCKRECEIPTS.DCK_DOCKID%TYPE
		    @sVOrder                   nvarchar(30), --R5DOCKRECEIPTS.DCK_ORDER%TYPE
		    @sVOrderOrg                nvarchar(15), --R5DOCKRECEIPTS.DCK_ORDER_ORG%TYPE
		    @sIssueuom                 nvarchar(30), --R5PARTS.PAR_UOM%TYPE
		    @sVDockRstatus             nvarchar(4), --R5DOCKRECEIPTS.DCK_RSTATUS%TYPE 
		    @sVRecvAuto                nvarchar(4),
			@nReturn				   int,

	        @sOrd_code nvarchar(30), 
		    @sOrd_org  nvarchar(15),

	        @sOrl_order 	nvarchar(30),
		    @nOrl_ordline 	numeric(8,0),
		    @sOrl_order_org nvarchar(15),
		    @sOrl_part_org 	nvarchar(15),
		    @sOrl_part 		nvarchar(30),
		    @sOrl_ref 		nvarchar(50),
		    @sOrl_puruom 	nvarchar(30),
    		@nOrl_ordqty 	numeric(24,6),
    		@nOrl_recvqty 	numeric(24,6),
			@nOrl_multiply 	numeric(10,4)
BEGIN
	/* Initialize */
    set @sChk    = N'0'
	set @nOrderlines = 0
	set @nAttach = 0

	set @nLine = 0
	/* Get dock related information */
    SELECT @sVDockOrg = dck_org,
            @sVSupplier = dck_supplier,
            @sVSupplierOrg = dck_supplier_org,
            @sVStore = dck_dockid,
            @sVOrder = dck_order,
            @sVOrderOrg = dck_order_org,
            @sVDockRstatus = dck_rstatus
    FROM   r5dockreceipts
    WHERE  dck_code = @sCcode
	if @@ROWCOUNT = 0
	begin
		set @sChk = N'1'
        RETURN
	end

    IF (@sVDockRstatus <> N'U')
	begin
        set @sChk = N'2'
        RETURN
    end
	execute @nReturn = O7DFLT @sVIncrNum OUTPUT, N'INCRLINO', @sCheckResult OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1
	set @nVIncrNum = cast(@sVIncrNum as int)
    IF @sCheckResult <> N'0'
	begin
        set @sChk = N'999'
        RETURN
    end

	set @nVIncrNum = isnull( @nVIncrNum, 10 )

	declare cCursor_order cursor local for
	   SELECT ord_code, ord_org
	   FROM   r5orders o
	   WHERE ord_supplier     = @sVSupplier
	   AND   ord_supplier_org = @sVSupplierOrg
	   AND   ord_org          = isnull(@sVOrderOrg, @sVDockOrg)
	   AND   ord_rstatus      = N'A'
	   AND   ord_code         LIKE  isnull(@sVOrder,N'%')
	   AND   ord_store        = @sVStore
	   AND EXISTS (
	     		SELECT N'x'
			FROM    r5orderlines
	     		WHERE   orl_order = o.ord_code
	     		AND     orl_active = N'+'
		        AND     orl_part IS NOT NULL
	    		AND     orl_part_org IS NOT NULL
     	      		)

	open cCursor_order
	fetch next from cCursor_order into @sOrd_code, @sOrd_org
	while @@fetch_status = 0
	begin
		declare cCursor_orderline cursor local for
		    SELECT orl_order,
		           orl_ordline,
		           orl_order_org,
		           orl_part_org,
		     	   orl_part,
		     	   orl_ref,
		           orl_puruom,
		           isnull(orl_ordqty,0)  orl_ordqty,
		           isnull(orl_recvqty,0)+isnull(orl_scrapqty,0) orl_recvqty,
		     	   orl_multiply
	     	FROM   R5ORDERLINES
	     	WHERE  orl_order = @sOrd_code
	     	AND    orl_order_org = @sOrd_org
	     	AND    orl_rtype NOT LIKE N'S%'
		AND    orl_active = N'+'
		AND    orl_part IS NOT NULL
     	AND    orl_part_org IS NOT NULL
		AND    NOT EXISTS (
		   	   		SELECT 'x'
					FROM    r5packingslip,r5dockreceipts
					WHERE   psl_order = orl_order
					AND     psl_order_org = orl_order_org
					AND     psl_ordline = orl_ordline
					AND     psl_dock    = dck_code
                    AND     dck_rstatus = N'U'
					group by psl_order
					having sum(psl_recvqty) = orl_ordqty 
						  )		
		ORDER BY orl_ordline		
		open cCursor_orderline
		fetch next from cCursor_orderline into  @sOrl_order, 
												@nOrl_ordline,
											    @sOrl_order_org ,
											    @sOrl_part_org 	,
												@sOrl_part 		,
												@sOrl_ref 		,
											    @sOrl_puruom 	,
									    		@nOrl_ordqty 	,
									    		@nOrl_recvqty 	,
												@nOrl_multiply 	
		while @@fetch_status = 0
		begin
			set @nAttach = 0
		    SELECT @nDck_qty = isnull( SUM(isnull(dkl_countqty,dkl_recvqty)),0 )

		    FROM   r5docklines d
		    WHERE  dkl_order       = @sOrd_code
		    AND    dkl_order_org   = @sOrd_org
		    AND    dkl_ordline     = @nOrl_ordline
		    AND    dkl_linerstatus NOT IN(N'A',N'C')

		    SELECT @nSmrecvqty = isnull(SUM(trl_qty),0)
		    FROM   r5translines l,r5transactions t
		    WHERE  l.trl_trans     = t.tra_code
		    AND    l.trl_order     = @sOrd_code
		    AND    l.trl_order_org = @sOrd_org
		    AND    l.trl_ordline   = @nOrl_ordline
		    AND    t.tra_rstatus   NOT IN (N'A',N'C')

		    SELECT @sIssueuom = par_uom
		    FROM   r5parts
		    WHERE  par_code = @sOrl_part
		    AND    par_org  = @sOrl_part_org

		    set @nPendqty = @nOrl_ordqty - (@nOrl_recvqty+@nDck_qty+@nSmrecvqty)

		    IF @sIssueuom <> @sOrl_puruom
		   	    set @nOrlqty = @nPendqty/@nOrl_multiply
		    ELSE
		   	    set @nOrlqty = @nPendqty

		    SELECT @nAttach = COUNT(1)
		    FROM   r5packingslip, r5dockreceipts
		    WHERE  psl_order     = @sOrd_code
		    AND    psl_ordline   = @nOrl_ordline
		    AND    psl_recvqty   >= @nOrl_ordqty
		    AND    psl_dock      = dck_code
	        AND    dck_rstatus   = N'U'

		 SELECT @nMaxpslline = COALESCE(MAX(psl_line), 0) 
  		 FROM R5PACKINGSLIP WHERE psl_dock = @sCcode

		set @nLine = @nMaxpslline + @nVIncrNum

	        IF @nAttach = 0 
			begin
	  	        IF @nPendqty > 0
				begin
		            set @nOrderlines = @nOrderlines + 1; 

			SELECT @sVRecvAuto = INS_DESC 
  			FROM R5INSTALL WHERE ins_code = 'RECVAUTO'

			IF @sVRecvAuto = 'NO'
				begin
				   set @nOrlqty = 0;
				end

	                INSERT INTO r5packingslip (psl_dock,
	                                            psl_line,
	                                            psl_order,
	                                            psl_ordline,
	                                            psl_order_org,
	                                            psl_part,
	                                            psl_part_org,
	                                            psl_supplierref,
	                                            psl_deluom,
	                                            psl_delqty,
	                                            psl_recvqty,
	                                            psl_multiply
	                                         )
	                VALUES (@sCcode,
	                         @nLine,
	                         @sOrl_order,
	                         @nOrl_ordline,
	                         @sOrl_order_org,
	                         @sOrl_part,
	                         @sOrl_part_org,
	                         @sOrl_ref,
	                         @sOrl_puruom,
	                         null


-- ========================================

CREATE PROCEDURE O7CRFDP1 
				@nPpopk         NUMERIC,
				@dDue			DATETIME,
				@nFreq			INTEGER,
				@sCalendaruom	NVARCHAR(10),
                @sPerformonweek NVARCHAR(1),
                @nPerformonday  NUMERIC(1),
				@sObject		NVARCHAR(30),
				@sObjectorg		NVARCHAR(15),
				@dDeactive		DATETIME,				
				@schk			NVARCHAR(4)  OUTPUT

AS
	SET NOCOUNT ON

	DECLARE @dDate			DATETIME
	DECLARE @denddate		DATETIME
	DECLARE @nFreqdays		NUMERIC(8,0)
	DECLARE @iFuturedays	INTEGER
	DECLARE @iSeqno			INTEGER

	SET @iseqno = 1

	/* Get number of days in which future duplicate events should be created.*/
	SELECT @iFuturedays = ins_desc
	FROM   r5install
	WHERE  ins_code = N'FUTUREPM'
	if @@ROWCOUNT <> 1 OR ISNULL( @iFuturedays, 0 ) = -1
		RETURN

	/* Delete all future duplicates of ppo record first. */
	IF @nPpopk IS NOT NULL
		DELETE FROM r5futureduplicates
		WHERE fdp_ppopk = @nPpopk

	/* Calculate calendar based. */
	IF coalesce( @nFreq, 0 ) > 0 
		BEGIN
			SET @nFreqdays= dbo.o7gtfreq( @nFreq, @sCalendaruom, @dDue )
			SET @dDate  = @dDue
		END

	/* Create future duplicates. */
	IF coalesce( @nFreqdays, 0 ) > 0 AND @dDate IS NOT NULL 
		BEGIN
			/* Calculate end date ( 5 future duplicate events will always be created ).*/
			SET @denddate = dbo.F_GREATEST_DATE( @dDate + ( 5 *  @nFreqdays  ), @dDate + @iFuturedays)
			WHILE @dDate < dbo.F_LEAST_DATE( @denddate,  COALESCE( @dDeactive, @denddate ) )
				BEGIN
					/* Do actual insert. */
					INSERT INTO r5futureduplicates ( fdp_ppopk, fdp_seqno, fdp_date )
					VALUES ( @nPpopk, @iSeqno, @dDate )
					SET @dDate = @dDate + dbo.o7gtfreq( @nFreq, @sCalendaruom, @dDate ) 
					SET @dDate = dbo.o7gtdate( @dDate, @sPerformonweek, @nPerformonday )
					SET @iSeqno = @iSeqno + 1
				END
		END


