create  procedure O7CRORL1 
	@sOrl_order		nvarchar(30),
	@sOrl_orderorg	nvarchar(15),
	@nOrl_ordline	int,
	@dOrl_due		datetime,
	@nOrl_price		numeric(24,6),
	@sOrl_curr		nvarchar(3),
	@nOrl_exch		numeric(24,12),
	@nOrl_ordqty	numeric(24,6),
	@sOrl_costcode	nvarchar(30),
	@sOrl_project	nvarchar(20),
	@sOrl_projbud	nvarchar(20),
	@sOrl_event		nvarchar(30),
	@nOrl_act		int,
	@sOrl_rtype		nvarchar(4),
	@sOrl_type		nvarchar(4),
	@sOrl_active	nvarchar(1),
	@sOrl_status	nvarchar(4),
	@sOrl_rstatus	nvarchar(4),
	@sChk			nvarchar(5)	OUTPUT
as
begin
	SET NOCOUNT ON
	declare @sCstore	nvarchar(15)	/*r5orders.ord_store%type;*/
	/* Initialize */
    set @sChk = N'0'
	/* Check mandatory parameters                    */
	/* W1024, W10344 - Check that cppm <> NULL        */
    IF @sOrl_order    IS NULL
    OR @sOrl_orderorg IS NULL
    OR @nOrl_ordline  IS NULL
    OR @dOrl_due      IS NULL
    OR @nOrl_price	  IS NULL 
	begin
        set @sChk = N'1'
        return
    end
    SELECT @sCstore  = ord_store
    FROM   r5orders
    WHERE  ord_code = @sOrl_order
    AND    ord_org  = @sOrl_orderorg 
    INSERT INTO r5orderlines (
               ORL_ORDER,
               ORL_ORDER_ORG,
               ORL_ORDLINE,
               ORL_STORE,
               ORL_DUE,
               ORL_PRICE,
               ORL_CURR,
               ORL_EXCH,
               ORL_ORDQTY,
               ORL_COSTCODE,
               ORL_PROJECT,
               ORL_PROJBUD,
               ORL_EVENT,
               ORL_ACT,
               ORL_RTYPE,
               ORL_TYPE,
               ORL_ACTIVE,
               ORL_STATUS,
               ORL_RSTATUS )
    VALUES (   @sOrl_order,
               @sOrl_orderorg ,
               @nOrl_ordline,
               @sCstore,
               @dOrl_due,
               @nOrl_price,
               @sOrl_curr,
               @nOrl_exch,
               @nOrl_ordqty,
               @sOrl_costcode,
               @sOrl_project,
               @sOrl_projbud,
               @sOrl_event,
               @nOrl_act,
               @sOrl_rtype,
               @sOrl_type,
               @sOrl_active,
               @sOrl_status,
               @sOrl_rstatus  ) 
	/* checking error for possible duplicate key errors */
    if @@ERROR <> 0
	begin
		set @sChk = N'2'
		return
	end 
    return
end


