CREATE PROCEDURE O7CRTOU1
		@sEvent      nvarchar(30),
		@nAct        numeric(8),
		@dDatebooked datetime,
		@dDateused   datetime,
		@sMrc        nvarchar(15),
		@sTool       nvarchar(12),
		@nTothours   numeric(12,2),
		@nTariff     numeric(24,6),
		@nCost       numeric(24,6),
		@nTotqty     numeric(24,6),
		@sAction     nvarchar(4),
		@nObjects    integer,
		@sDesc       nvarchar(80),
		@sMisc       nvarchar(1),
		@sSplitusage nvarchar(1)
AS
	SET NOCOUNT ON
	declare @sCode		nvarchar(30)
	declare @nHours     numeric(24,6)
	declare @nRecs      integer
	declare @sX			nvarchar(1)
	declare @nQty		numeric(24,6)

	set @nHours = ROUND( @nTothours / @nObjects, 2 )
	set @nRecs = 0

	declare c_evt cursor local for SELECT evt_code
									FROM   r5events
									WHERE  evt_routeparent = @sEvent
									AND    ( @sSplitusage = N'A' OR ( @sSplitusage = N'O' AND evt_rstatus <> N'C' ) )
   									AND    EXISTS( SELECT N'x'
												  FROM   r5activities
												  WHERE  act_event = evt_code
												  AND    act_act   = @nAct )
									ORDER BY evt_code
	open c_evt
	fetch next from c_evt into	@sCode
	IF @sMisc = '+'
		BEGIN
		/* For additional tool cost, split the qty. */
			set @nQty   = ROUND( @nTotqty / @nObjects, 6 );
			set @nHours = @nTothours;
		END
	ELSE
		BEGIN
		/* For normal tool cost, split the hours. */
			set @nHours = ROUND( @nTothours / @nObjects, 2 );
			set @nQty   = @nTotqty;
		END

	while @@FETCH_STATUS = 0
		begin
			set @nRecs = @nRecs + 1
			IF @nRecs = @nObjects
			IF @sMisc = '+'
				BEGIN
				/* For additional tool cost, calculate quantity for last child, to avoid rounding differences. */
					set @nQty = @nTotqty - ( @nQty * ( @nRecs - 1 ) );
				END
			ELSE
				BEGIN
				/* For normal tool cost, calculate number of hours for last child, to avoid rounding differences. */
					set @nHours = @nTothours - ( @nHours * ( @nRecs - 1 ) )
				END

			IF @sAction IN ( N'UPD', N'DEL' )
				begin
				/* On update of delete of parent usage, remove child record. */
					DELETE FROM r5toolusage
					WHERE  tou_event    = @sCode
					AND    tou_act      = @nAct
					AND    tou_mrc      = @sMrc
					AND    tou_tool     = @sTool
					AND    tou_dateused = @dDateused
				end

			IF @sAction IN ( N'INS', N'UPD' )
				INSERT INTO r5toolusage
					(   tou_event,
					tou_act,
					tou_datebooked,
					tou_dateused,
					tou_mrc,
					tou_tool,
					tou_hours,
					tou_tariff,
					tou_cost,
					tou_qty,
					tou_routerec,
					tou_desc,
					tou_misc,
					tou_splitusage )
				VALUES (
					@sCode,
					@nAct,
					@dDatebooked,
					@dDateused,
					@sMrc,
					@sTool,
					@nHours,
					@nTariff,
					@nHours * @nTariff * @nQty,
					@nQty,
					N'+',
					@sDesc,
					@sMisc,
					N'N' )

			fetch next from c_evt into	@sCode
  		end
	close c_evt
	deallocate c_evt


