CREATE PROCEDURE O7CRTRL2
	@sTranscode		nvarchar(30),	
	@sTransorg		nvarchar(15),	
	@sEvent			nvarchar(30),	
	@sOldobj		nvarchar(30),	
	@sOldoborg		nvarchar(15),	
	@sOldlot		nvarchar(12),	
	@sNewobj		nvarchar(30),	
	@sNewoborg		nvarchar(15),	
	@sCobrtype		nvarchar(4),	
	@sCobtype		nvarchar(4),	
	@sPart			nvarchar(30),	
	@sPartorg		nvarchar(15),	
	@sStore			nvarchar(15),	
	@sBin			nvarchar(15),	
	@sLot			nvarchar(12),	
	@sRepair		nvarchar(1),
	@sChk			nvarchar(4) OUTPUT 
AS 
	SET NOCOUNT ON
	declare @sType			nvarchar(4)		
	declare @sRtype			nvarchar(4)		
	declare @nPrice			numeric(24,6)	
	declare @nCore			numeric(24,6)	
	declare @sStatus		nvarchar(8)		
	declare @sCheckresult		nvarchar(4)
	declare @dTempDate		datetime
	declare @nReturn		integer
    declare @sCostcode      nvarchar(30)


	set @sChk           = N'0'
	set @sCheckresult   = N'0'
    set @sCostcode      = null

	IF coalesce( @sRepair, N'-' ) = N'-' 
		begin
			set @sRtype = N'I'
			execute @nReturn = R5O7_O7UCODE @sType OUTPUT, N'I', N'TRTP', @sCheckresult OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1
		end
	ELSE
		begin
			set @sRtype = N'RR'
			execute @nReturn = R5O7_O7UCODE @sType OUTPUT, N'RR', N'TRTP', @sCheckresult OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1

			execute @nReturn = O7GTCORE @nCore OUTPUT, @sStore, @sPart, @sPartorg, @sTransorg, null, null 
			if @@ERROR <> 0 or @nReturn <> 0
				return -1
			set @nCore = coalesce(@nCore,0)
		end

	set @nPrice = isnull(dbo.O7GETPRC(@sStore, @sPart, @sPartorg, @sTransorg, N'B', null, null), 0 )

    select @sCostcode = evt_costcode from r5events where evt_code = @sEvent

	execute @nReturn = O7GTTIME @dTempDate OUTPUT, @sTransorg 
	if @@ERROR <> 0 or @nReturn <> 0
		return -1	
	set @dTempDate = dbo.F_TRUNC_DATE( @dTempDate, N'DD' )

	INSERT INTO r5translines
	(   trl_trans,
		trl_type,
		trl_rtype,
		trl_line,
		trl_date,
        trl_costcode,
		trl_event,
		trl_part,
		trl_part_org,
		trl_obtype,
		trl_obrtype,
		trl_object,
		trl_object_org,
		trl_lot,
		trl_bin,
		trl_store,
		trl_price,
		trl_qty,
		trl_io )
	VALUES (
		@sTranscode,
		@sType,
		@sRtype,
		10,
		@dTempDate,
        @sCostcode,
		@sEvent,
		@sPart,
		@sPartorg,
		@sCobtype,
		@sCobrtype,
		@sOldobj,
		@sOldoborg,
		@sOldlot,
		@sBin,
		@sStore,
		coalesce( @nCore, @nPrice ),
		-1,
		N'-1' )

	execute @nReturn = R5O7_O7UCODE @sType OUTPUT, N'I', N'TRTP', @sCheckresult OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	INSERT INTO r5translines
	 (   trl_trans,
		 trl_type,
		 trl_rtype,
	     trl_line,
	     trl_date,
         trl_costcode,
		 trl_event,
		 trl_part,
		 trl_part_org,
		 trl_obtype,
		 trl_obrtype,
		 trl_object,
		 trl_object_org,
		 trl_lot,
		 trl_bin,
		 trl_store,
		 trl_price,
		 trl_qty,
		 trl_io )
	VALUES (
		 @sTranscode,
		 @sType,
		 N'I',
		 20,
		 @dTempDate,
         @sCostcode,
		 @sEvent,
		 @sPart,
		 @sPartorg,
		 @sCobtype,
		 @sCobrtype,
		 @sNewobj,
		 @sNewoborg,
		 @sLot,
		 @sBin,
		 @sStore,
		 @nPrice,
		 1,
		 N'-1' )


