    DECLARE @nQty           NUMERIC(10,2)
    DECLARE @sUom           NVARCHAR(30)
    DECLARE @sLabortype     NVARCHAR(4)
    DECLARE @sLaborrtype    NVARCHAR(4)
    DECLARE @sTskrpc        NVARCHAR(4)
    DECLARE @sTskwap        NVARCHAR(4)
    DECLARE @sTsktpf        NVARCHAR(4)
    DECLARE @sTskmanufact   NVARCHAR(24)
    DECLARE @sTsksyslevel   NVARCHAR(30)
    DECLARE @sTskasmlevel   NVARCHAR(30)
    DECLARE @sTskcomplevel  NVARCHAR(30)

    DECLARE cCevents CURSOR LOCAL FOR SELECT e.evt_code,
                             COALESCE( e.evt_target, dbo.F_TRUNC_DATE( dbo.o7gttime2( e.evt_org ), N'DD' ) ),
                             e.evt_mrc
                      FROM   r5events e
                      WHERE  e.evt_ppm      = @sCppm
                      AND    e.evt_rstatus <= N'B'

    /* Initialize  */
    set @sTask =  @sCtask
    set @sMatlist = @sCmatlist
    set @sChk  = N'0'

    IF @sInsupd       IS NULL
    OR @sCppm         IS NULL
    OR @nNppmact      IS NULL
    OR @nNduration    IS NULL
    OR @sCspecial     IS NULL
    OR @sChire        IS NULL
    OR @nNtime        IS NULL
    OR @sCfixh        IS NULL
    OR @sCminhours    IS NULL
    OR @nNstart       IS NULL
    OR @sInsupd       IS NULL
    OR @sInsupd NOT IN( N'INS', N'UPD' )
    begin
        set @sChk  = N'1'
        return
    end
    /* Get current approved revisons */
    IF @sTask IS NOT NULL
    begin
        SELECT @nNtaskrev = tsk_revision
        FROM   r5tasks
        WHERE  tsk_code = @sTask
        AND    tsk_revrstatus = N'A';
        if @@ERROR <> 0
            set @sTask = null
    end
    IF @sMatlist  IS NOT NULL
    begin
        SELECT @nNmatlrev = mtl_revision
        FROM   r5matlists
        WHERE  mtl_code = @sMatlist
        AND    mtl_revrstatus = N'A';
        if @@ERROR <> 0
            set @sMatlist = null
    end
    /* get PM Schedule Activity UDF's*/
    SELECT @sUdfchar01   = ppa_udfchar01,
             @sUdfchar02   = ppa_udfchar02,
             @sUdfchar03   = ppa_udfchar03,
             @sUdfchar04   = ppa_udfchar04,
             @sUdfchar05   = ppa_udfchar05,
             @sUdfchar06   = ppa_udfchar06,
             @sUdfchar07   = ppa_udfchar07,
             @sUdfchar08   = ppa_udfchar08,
             @sUdfchar09   = ppa_udfchar09,
             @sUdfchar10   = ppa_udfchar10,
             @sUdfchar11   = ppa_udfchar11,
             @sUdfchar12   = ppa_udfchar12,
             @sUdfchar13   = ppa_udfchar13,
             @sUdfchar14   = ppa_udfchar14,
             @sUdfchar15   = ppa_udfchar15,
             @sUdfchar16   = ppa_udfchar16,
             @sUdfchar17   = ppa_udfchar17,
             @sUdfchar18   = ppa_udfchar18,
             @sUdfchar19   = ppa_udfchar19,
             @sUdfchar20   = ppa_udfchar20,
             @sUdfchar21   = ppa_udfchar21,
             @sUdfchar22   = ppa_udfchar22,
             @sUdfchar23   = ppa_udfchar23,
             @sUdfchar24   = ppa_udfchar24,
             @sUdfchar25   = ppa_udfchar25,
             @sUdfchar26   = ppa_udfchar26,
             @sUdfchar27   = ppa_udfchar27,
             @sUdfchar28   = ppa_udfchar28,
             @sUdfchar29   = ppa_udfchar29,
             @sUdfchar30   = ppa_udfchar30,
             @nUdfnum01    = ppa_udfnum01,
             @nUdfnum02    = ppa_udfnum02,
             @nUdfnum03    = ppa_udfnum03,
             @nUdfnum04    = ppa_udfnum04,
             @nUdfnum05    = ppa_udfnum05,
             @dUdfdate01   = ppa_udfdate01,
