CREATE PROCEDURE dbo.O7DWETLDM_INSERTPARTSDAILYSNAPSHOTRECS @nRet int OUTPUT, @tN_runNumber numeric(18,0),
									@tS_tenantID           nvarchar(50),
									@tS_loadFlag           nvarchar(1),   /* r5dwetlrunctrl.run_loadFlag%TYPE, */
									@tS_loadType           nvarchar(255),
									@tD_loadFromDate       datetime,
									@tD_loadToDate         datetime,
									@tD_nextStartDate      datetime,
									@tD_minWarehouseDate   datetime,
									@tS_purgeFlag          nvarchar(1),   /*r5dwetlrunctrl.run_purgeflag%TYPE, */
									@tD_purgeToDate        datetime,
									@tS_defaultLanguage    nvarchar(2),   /* r5languages.lan_code%TYPE, */
									@tS_defaultCurrency    nvarchar(200),   /* r5install.ins_desc%TYPE, */
									@tS_oldDefaultCurrency nvarchar(3),   /* r5dwetlrunctrl.run_defcur%TYPE, */
									@tB_debug              bit,
									@tB_isRepair           bit,
									@tD_originalLoadFromDate datetime,
									@tD_originalLoadToDate datetime,
									@tB_hasObjectType2SCDChanges bit,
									@tB_hasSupplierType2SCDChanges bit,
									@tD_loadFirstDate      datetime,
									@dWorkDate datetime
as
SET NOCOUNT ON
SET IMPLICIT_TRANSACTIONS OFF
declare @nDateKey numeric(18,0) --number
declare @nExistingRecordCount int --pls_integer = 0
declare @nReturn int
declare @sOP_INCREMENTAL_LOAD nvarchar(30)
declare @sCommitFreq nvarchar(30)
declare @nCommitFreq int
declare @nNumInserts int
declare @nQtyOrdered	numeric(24,6)
declare @sMustTruncPartsDailySnap nvarchar(1)
declare @rNfact_zas_datekey                 numeric(18,0) --r5dwpartsdailysnap.zas_datekey%TYPE,
declare @rNfact_zas_partkey                numeric(18,0) -- r5dwpartsdailysnap.zas_storekey%TYPE,
declare @rSfact_zas_defcur                  nvarchar(4)   -- r5dwpartsdailysnap.zas_defcur%TYPE,
declare @rSfact_zas_orgcur                  nvarchar(4)   -- r5dwpartsdailysnap.zas_orgcur%TYPE,
declare @rNfact_zas_valueonhanddefcur       numeric(24,6) -- r5dwpartsdailysnap.zas_valueonhanddefcur%TYPE,
declare @rNfact_zas_valueonhandorgcur       numeric(24,6) -- r5dwpartsdailysnap.zas_valueonhandorgcur%TYPE,
declare @rNfact_zas_valuetoberepaireddefcur numeric(24,6) --r5dwpartsdailysnap.zas_valuetoberepaireddefcur%TYPE,
declare @rNfact_zas_valuetoberepairedorgcur numeric(24,6) --r5dwpartsdailysnap.zas_valuetoberepairedorgcur%TYPE,
declare @rNfact_zas_valueintransitdefcur    numeric(24,6) --r5dwpartsdailysnap.zas_valueintransitdefcur%TYPE,
declare @rNfact_zas_valueintransitorgcur    numeric(24,6) --r5dwpartsdailysnap.zas_valueintransitorgcur%TYPE,
declare @rNfact_zas_valueatshopdefcur       numeric(24,6) --r5dwpartsdailysnap.zas_valueatshopdefcur%TYPE,
declare @rNfact_zas_valueatshoporgcur       numeric(24,6) --r5dwpartsdailysnap.zas_valueatshoporgcur%TYPE,
declare @rNfact_zas_valueatsupplierdefcur   numeric(24,6) --r5dwpartsdailysnap.zas_valueatsupplierdefcur%TYPE,
declare @rNfact_zas_valueatsupplierorgcur   numeric(24,6) --r5dwstoresdailysnap.zas_valueatsupplierorgcur%TYPE)
declare @rNfact_zas_quantityonhand			numeric(24,6) --r5dwpartsdailysnap.zas_quantityonhand%TYPE,
declare @rNfact_zas_quantitytoberepaired	numeric(24,6) --r5dwpartsdailysnap.zas_quantitytoberepaired%TYPE,
declare @rNfact_zas_quantityintransit		numeric(24,6) --r5dwpartsdailysnap.zas_quantityintransit%TYPE,
declare @rNfact_zas_quantityatshop			numeric(24,6) --r5dwpartsdailysnap.zas_quantityatshop%TYPE,
declare @rNfact_zas_quantityatsupplier		numeric(24,6) --r5dwpartsdailysnap.zas_quantityatsupplier%TYPE);
begin

	set @nRet = 0
	set @dWorkDate = dbo.F_TRUNC_DATE(@dWorkDate, N'DD')
	--run initialization code if necessary
	execute @nReturn = O7DWETLDM_PACKAGE_INIT
	if @@ERROR <> 0 or @nReturn <> 0
	begin
		return -1
	end
	--run initialization code if necessary
	execute @nReturn = O7DWETL_PACKAGE_INIT
	if @@ERROR <> 0 or @nReturn <> 0
	begin
		return -1
	end

	execute @nReturn = O7DWETLDM_GETDATEDIMENSIONKEY @nDateKey OUTPUT, @dWorkDate
	if @@ERROR <> 0 OR @nReturn <> 0
		return -1

	execute @nReturn = GET_PACKAGE_VARIABLE N'O7DWETL', N'OP_INCREMENTAL_LOAD', @sOP_INCREMENTAL_LOAD OUTPUT
		if @@ERROR <> 0 or @nReturn <> 0
		begin
			return -1	
		end

	execute @nReturn = GET_PACKAGE_VARIABLE N'O7DWETLDM', N'commitFreq', @sCommitFreq OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0 or ( @sCommitFreq is not null and isnumeric(@sCommitFreq) = 0 )
		return -1
	set @nCommitFreq = cast(@sCommitFreq as int)

	declare cSource cursor local for
	  select @nDateKey,
                 isnull(zpa_key,-1),
  		     @tS_defaultCurrency,
		     org_curr,
	       sum(dbo.O7DWETLDM_TODEFCURR((coalesce(ztp_qtyonhand,0) * coalesce(ztp_price,0)), org_curr, @tS_defaultCurrency, null, @dWorkDate)),
	       sum(coalesce(ztp_qtyonhand,0) * coalesce(ztp_price,0)),
	       sum(dbo.O7DWETLDM_TODEFCURR((coalesce(ztp_qtytorepair,0) * coalesce(ztp_corevalue, ztp_price,0)), org_curr, @tS_defaultCurrency, null, @dWorkDate)),
	       sum(coalesce(ztp_qtytorepair,0) * coalesce(ztp_corevalue, ztp_price,0)),
	       sum(dbo.O7DWETLDM_TODEFCURR((coalesce(ztp_qtyintransit,0) * coalesce(ztp_price,0)), org_curr, @tS_defaultCurrency, null, @dWorkDate)),
	       sum(coalesce(ztp_qtyintransit,0) * coalesce(ztp_price,0)),
	       sum(dbo.O7DWETLDM_TODEFCURR((coalesce(ztp_qtyatshop,0) * coalesce(ztp_corevalue, ztp_price,0)), org_curr, @tS_defaultCurrency, null, @dWorkDate)),
	       sum(coalesce(ztp_qtyatshop,0) * coalesce(ztp_corevalue, ztp_price,0)),
	       sum(dbo.O7DWETLDM_TODEFCURR((coalesce(ztp_qtyatsupplier,0) * coalesce(ztp_corevalue, ztp_price,0)), org_curr, @tS_defaultCurrency, null, @dWorkDate)),
	       sum(coalesce(ztp_qtyatsupplier,0) * coalesce(ztp_corevalue, ztp_price,0)),
	       sum(coalesce(ztp_qtyonhand,0)),
	       sum(coalesce(ztp_qtytorepair,0)),
	       sum(coalesce(ztp_qtyintransit,0)),
	       sum(coalesce(ztp_qtyatshop,0)),
	       sum(coalesce(ztp_qtyatsupplier,0))
          from   r5organization,
                 r5dwparts,
                 r5dwtmpparts
          where  ztp_saveparthistory = N'+'
          and    ztp_partorg = org_code
          and    ztp_part = zpa_code
	    group by isnull(zpa_key, -1),
                   org_curr
	open cSource
	fetch next from cSource into  @rNfact_zas_datekey                 ,
				      @rNfact_zas_partkey            ,
					  @rSfact_zas_defcur                  ,
					  @rSfact_zas_orgcur                  ,
					  @rNfact_zas_valueonhanddefcur       ,
					  @rNfact_zas_valueonhandorgcur       ,
					  @rNfact_zas_valuetoberepaireddefcur ,
					  @rNfact_zas_valuetoberepairedorgcur ,
					  @rNfact_zas_valueintransitdefcur    ,
					  @rNfact_zas_valueintransitorgcur    ,
					  @rNfact_zas_valueatshopdefcur       ,
					  @rNfact_zas_valueatshoporgcur       ,
					  @rNfact_zas_valueatsupplierdefcur,
					@rNfact_zas_valueatsupplierorgcur,
					@rNfact_zas_quantityonhand,			
					@rNfact_zas_quantitytoberepaired,	
					@rNfact_zas_quantityintransit,		
					@rNfact_zas_quantityatshop,			
					@rNfact_zas_quantityatsupplier							  
    while @@fetch_status = 0
		begin
			set @nExistingRecordCount = 0

			set @nQtyOrdered = isnull(dbo.o7dwetldm_getOrderedQty(@rNfact_zas_partkey,@dWorkDate), 0)

			execute @nReturn = GET_PACKAGE_VARIABLE N'O7DWETLDM', N'MustTruncPartsDailySnap', @sMustTruncPartsDailySnap OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1

			if @tS_loadType = @sOP_INCREMENTAL_LOAD and (@tB_isRepair = 0 or @sMustTruncPartsDailySnap = N'false')
				begin
					select @nExistingRecordCount = count(1)
					from   r5dwpartsdailysnap
					where  zas_datekey      = @rNfact_zas_datekey
					and    zas_partkey


